DELIMITER $$
CREATE TRIGGER `galpao_movimentacao_AFTER_UPDATE` AFTER UPDATE ON `galpao_movimentacao`
 FOR EACH ROW BEGIN
	declare DifNumAves int;
    IF (NEW.IDGalpao = OLD.IDGalpao) THEN
    SELECT OLD.QtdMortes - NEW.QtdMortes INTO DifNumAves;
    IF (DifNumAves <> 0) THEN
		UPDATE galpao SET  NumAves = (NumAves +DifNumAves) WHERE ID = NEW.IDGalpao;
    END IF;
    ELSE 
		UPDATE galpao SET NumAves = (NumAves - NEW.QtdMortes) WHERE ID = NEW.IDGalpao;
        UPDATE galpao SET NumAves = (NumAves + NEW.QtdMortes) WHERE ID = OLD.IDGalpao;
    END IF;
    
END
$$
DELIMITER ;

